-- Solo para una base nueva cuyo nombre empiece por Motherson_L1_MVP_.
IF DB_NAME() NOT IN ('Motherson_L1_MVP_Desarrollo','Motherson_L1_MVP_Pruebas') THROW 51000,'Base destino no autorizada',1;
IF OBJECT_ID('dbo.REGISTRO') IS NOT NULL RETURN;
SET XACT_ABORT ON; BEGIN TRANSACTION;
CREATE TABLE dbo.ESTACION(id_estacion int IDENTITY PRIMARY KEY,id_linea int NOT NULL CHECK(id_linea=1),nombre_estacion nvarchar(100) NOT NULL,UNIQUE(id_linea,nombre_estacion));
CREATE TABLE dbo.ESTANTERIA(id_estanteria int IDENTITY PRIMARY KEY,id_estacion int NOT NULL REFERENCES dbo.ESTACION,estanteria nvarchar(80) NOT NULL,nivel nvarchar(30) NOT NULL,cajas_estanteria int NULL CHECK(cajas_estanteria>0),UNIQUE(id_estacion,estanteria,nivel));
CREATE TABLE dbo.PUESTO_LOGISTICO(id_puesto int IDENTITY PRIMARY KEY,nombre nvarchar(120) NOT NULL UNIQUE,tipo nvarchar(60) NULL);
CREATE TABLE dbo.MATERIAL(numero_parte varchar(100) COLLATE Latin1_General_100_BIN2 PRIMARY KEY,id_puesto int NOT NULL REFERENCES dbo.PUESTO_LOGISTICO,descripcion nvarchar(250) NULL,uso nvarchar(150) NULL,cantidad_por_caja int NULL CHECK(cantidad_por_caja>0),minimo int NULL CHECK(minimo>=0));
CREATE TABLE dbo.UBICACION(id_ubicacion int IDENTITY PRIMARY KEY,numero_parte varchar(100) COLLATE Latin1_General_100_BIN2 NOT NULL REFERENCES dbo.MATERIAL,id_estanteria int NOT NULL REFERENCES dbo.ESTANTERIA,cantidad int NULL CHECK(cantidad>=0),version_concurrencia int NOT NULL DEFAULT 1 CHECK(version_concurrencia>0),UNIQUE(numero_parte,id_estanteria));
CREATE TABLE dbo.TURNO(id_turno int IDENTITY PRIMARY KEY,nombre_turno nvarchar(40) NOT NULL UNIQUE,hora_inicio time(0) NOT NULL,hora_fin time(0) NOT NULL,CHECK(hora_inicio<hora_fin));
CREATE TABLE dbo.USUARIOS(id_usuarios int IDENTITY PRIMARY KEY,id_puesto int NULL REFERENCES dbo.PUESTO_LOGISTICO,nombre_usuario nvarchar(80) NOT NULL UNIQUE,nombre_visible nvarchar(150) NULL,hash_contrasena nvarchar(500) NOT NULL,esta_activo bit NOT NULL,perfil varchar(20) NOT NULL CHECK(perfil IN('CONSULTA','ENTRADAS','MOVIMIENTOS','ADMINISTRADOR')));
CREATE TABLE dbo.REGISTRO(id_registro int IDENTITY PRIMARY KEY,id_usuarios int NOT NULL REFERENCES dbo.USUARIOS,id_ubicacion int NOT NULL REFERENCES dbo.UBICACION,id_turno int NULL REFERENCES dbo.TURNO,id_puesto int NOT NULL REFERENCES dbo.PUESTO_LOGISTICO,tipo_movimiento varchar(10) NOT NULL CHECK(tipo_movimiento IN('ENTRADA','SALIDA','APERTURA')),cantidad_movimiento int NOT NULL,cantidad_cajas int NULL,cantidad_por_caja_aplicada int NULL,saldo_anterior int NOT NULL CHECK(saldo_anterior>=0),saldo_posterior int NOT NULL CHECK(saldo_posterior>=0),fecha_movimiento datetime2(7) NOT NULL,fecha_hora_inicio datetime2(7) NOT NULL,fecha_hora_fin datetime2(7) NOT NULL,id_operacion uniqueidentifier NOT NULL UNIQUE,huella_peticion char(64) NOT NULL,origen varchar(24) NOT NULL CHECK(origen IN('CAPTURA_SIMULADA','APERTURA_SIMULADA','CAPTURA_REAL','APERTURA_REAL')),
 CONSTRAINT CK_REGISTRO_TIPO CHECK((tipo_movimiento='ENTRADA' AND cantidad_movimiento>0 AND cantidad_cajas IS NOT NULL AND cantidad_por_caja_aplicada IS NOT NULL AND cantidad_cajas>0 AND cantidad_por_caja_aplicada>0 AND CONVERT(bigint,cantidad_movimiento)=CONVERT(bigint,cantidad_cajas)*cantidad_por_caja_aplicada AND CONVERT(bigint,saldo_posterior)=CONVERT(bigint,saldo_anterior)+cantidad_movimiento) OR (tipo_movimiento='SALIDA' AND cantidad_movimiento>0 AND cantidad_cajas IS NULL AND cantidad_por_caja_aplicada IS NULL AND CONVERT(bigint,saldo_posterior)=CONVERT(bigint,saldo_anterior)-cantidad_movimiento) OR (tipo_movimiento='APERTURA' AND cantidad_movimiento>=0 AND cantidad_cajas IS NULL AND cantidad_por_caja_aplicada IS NULL AND saldo_anterior=0 AND saldo_posterior=cantidad_movimiento)),
 CHECK(fecha_hora_fin>=fecha_hora_inicio));
CREATE UNIQUE INDEX UQ_REGISTRO_APERTURA ON dbo.REGISTRO(id_ubicacion) WHERE tipo_movimiento='APERTURA';
CREATE INDEX IX_REGISTRO_FECHA ON dbo.REGISTRO(fecha_movimiento,id_registro);
CREATE INDEX IX_REGISTRO_UBICACION ON dbo.REGISTRO(id_ubicacion,fecha_movimiento,id_registro);
CREATE INDEX IX_UBICACION_ESTANTERIA ON dbo.UBICACION(id_estanteria);
EXEC('CREATE SCHEMA archivo');EXEC('CREATE SCHEMA reporting');
CREATE TABLE archivo.CORTE(id int PRIMARY KEY CHECK(id=1),maestro char(12) NOT NULL,revision int NOT NULL,corte_fuente datetime2(7) NOT NULL,fecha_carga datetime2(7) NOT NULL DEFAULT SYSUTCDATETIME(),huella_fuentes char(64) NOT NULL,sellado bit NOT NULL DEFAULT 0);
-- Copia binaria exacta de TODOS los archivos originales, incluidos eventos no normalizables.
CREATE TABLE archivo.FUENTE(nombre nvarchar(150) PRIMARY KEY,sha256 char(64) NOT NULL,filas int NOT NULL,contenido_gzip varbinary(max) NOT NULL);
CREATE TABLE archivo.EVENTO(id_registro_origen int PRIMARY KEY,id_version_origen int NOT NULL UNIQUE,id_posicion_origen int NULL,fecha_movimiento datetime2(7) NULL,tipo_evento nvarchar(100) NOT NULL,tipo_movimiento varchar(10) NULL,cantidad_piezas int NULL,cantidad_delta int NULL,numero_parte varchar(100) COLLATE Latin1_General_100_BIN2 NULL,id_puesto int NULL,id_estacion int NULL,id_estanteria int NULL,id_ubicacion int NULL,estacion nvarchar(100) NULL,estanteria nvarchar(80) NULL,nivel nvarchar(30) NULL,id_turno int NULL,id_usuario int NULL,responsable_simulado nvarchar(150) NULL,proceso_generador nvarchar(100) NULL,origen_declarado nvarchar(100) NULL,saldo_anterior int NULL,saldo_posterior int NULL,es_base bit NOT NULL);
CREATE INDEX IX_EVENTO_FECHA ON archivo.EVENTO(fecha_movimiento,id_registro_origen);
CREATE INDEX IX_EVENTO_PARTE ON archivo.EVENTO(numero_parte,fecha_movimiento) INCLUDE(tipo_movimiento,cantidad_piezas);

COMMIT;
